    19→    public void DataGasCost([ValueSource(nameof(Eip7883TestCases))] Eip7883TestCase test)
    20→    {
    21→        ReadOnlyMemory<byte> inputData = PrepareInput(test.BaseLength, test.ExpLength, test.ModulusLength);
    22→
    23→        IReleaseSpec? spec = test.FusakaEnabled ? Osaka.Instance : Prague.Instance;
    24→        long gas = ModExpPrecompile.Instance.DataGasCost(inputData, spec);
    25→        gas.Should().Be(test.Result);
    26→    }
