   114→    private static ReadOnlyMemory<byte> PrepareInput(UInt256 baseLength, UInt256 expLength, UInt256 modulusLength)
   115→    {
   116→        var inputBytes = new byte[(int)(96 + baseLength + expLength + modulusLength)];
   117→
   118→        Array.Copy(baseLength.ToBigEndian(), 0, inputBytes, 0, 32);
   119→        Array.Copy(expLength.ToBigEndian(), 0, inputBytes, 32, 32);
   120→        Array.Copy(modulusLength.ToBigEndian(), 0, inputBytes, 64, 32);
   121→        Array.Copy(GetInput(baseLength).ToArray(), 0, inputBytes, 96, (int)baseLength);
   122→        Array.Copy(GetInput(expLength).ToArray(), 0, inputBytes, 96 + (int)baseLength, (int)expLength);
   123→        Array.Copy(GetInput(modulusLength).ToArray(), 0, inputBytes, 96 + (int)(baseLength + expLength), (int)modulusLength);
   124→
   125→        return new ReadOnlyMemory<byte>(inputBytes);
   126→    }
   127→
